// LOWER SIXTH ARTS — Meteorology, part 2: Lessons 7–12 (distribution of temperature; moisture in the atmosphere)
// Rewritten from the teacher's course support (LSA_LESSONS_METEOROLOGY_2026) in our own words; facts checked and updated.
const D = (items, intro = 'The key terms of this lesson are defined as follows:') => ({ title: 'DEFINITIONS', intro, items });
const { B } = require('./lsamet_1');
const L = [];
const T2 = 'Energy in the Atmosphere', T3 = 'Moisture in the Atmosphere';

L.push({ no: 7, title: 'Geographical Factors Affecting Temperature', topic: T2, subtopic: 'Global Distribution of Heat (Temperature)', pointPerSlide: true,
  notions: 'Continentality, maritime influence, specific heat, relief, altitude, aspect, ocean currents, prevailing winds, cloud cover, urban heat island.',
  focus: 'Geographical factors that modify temperatures at the same latitude: land and sea, relief (altitude, aspect), ocean currents, winds, cloud cover, urbanisation.',
  competence: 'Learners are able to explain why places at the same latitude have different temperatures, with examples around Garoua.',
  objectives: ['Explain the different heating of land and water (continentality).', 'Explain the effects of altitude and aspect.', 'Explain the effects of ocean currents and winds.', 'Explain the double role of clouds.', 'Explain the urban heat island.'],
  recall: ['Temperature decreases with latitude.', 'The Harmattan brings hot, dry air.', 'Clouds reflect sunlight.'],
  situation: 'You spend Saturday afternoon in your grandmother\'s village, 30 km from Garoua. Coming back in the evening, as your bus enters the city around the Central Market, the air suddenly feels much hotter and stuffier than in the village. You ask: "We are at the same latitude, so why does the town feel like an oven compared to the village?"',
  sitQA: [['What is the problem in the situation?', 'The learner does not know the geographical factors that change temperature at the same latitude.'],
    ['Why is the town hotter than the village?', 'Tar and concrete store heat, and there are fewer trees: an urban heat island.'],
    ['Name another factor that changes temperature locally.', 'Altitude, nearness to water (Lagdo), winds or cloud cover.']],
  justification: 'This lesson explains local differences of temperature and the importance of green spaces in towns.',
  action: 'Plant and protect trees in town to reduce the urban heat island.',
  activities: [
    { sec: '1. LAND AND SEA', img: 'continentality_big.png', caption: 'Coastal and inland temperatures.', q: 'Why do places far inland have more extreme temperatures?', a: 'Land heats and cools quickly, while the sea moderates coastal temperatures.', noProj: 'compare Douala and Garoua.' },
    { sec: '2. RELIEF', img: 'f2t_kilimanjaro.jpg', caption: 'Snow on Kilimanjaro near the Equator.', q: 'Why is there snow on Kilimanjaro near the Equator?', a: 'Temperature falls with altitude (about 6.5 °C per 1,000 m).', noProj: 'calculate the fall of temperature for 2,000 m.' },
    { sec: '2. RELIEF', img: 'aspect_big.png', caption: 'The aspect of slopes.', q: 'What is aspect?', a: 'The direction a slope faces.', noProj: 'find a slope facing the sun.' },
    { sec: '3. CURRENTS AND WINDS', img: 'ocean_currents_big.png', caption: 'Warm and cold currents.', q: 'How does the cold Benguela Current affect Namibia?', a: 'It cools the coast and makes it dry.', noProj: 'locate Namibia.' },
    { sec: '4. TOWNS', img: 'heat_island_big.png', caption: 'The urban heat island.', q: 'Give two causes of the urban heat island.', a: 'Tar and concrete, heat from vehicles and machines, few trees, tall buildings (any two).', noProj: 'feel a tar road and grass at noon.' },
  ],
  summary: [
    D([['Continentality:', 'It is the effect of distance from the sea, which makes inland temperatures more extreme.'],
      ['Adret:', 'It is the slope that faces the sun (south-facing in the northern hemisphere), which is warmer and drier.'],
      ['Ubac:', 'It is the slope that faces away from the sun, which is cooler and more humid.'],
      ['Temperature lapsing:', 'It is the fall of temperature with height, on average 6.5 °C per 1,000 m.'],
      ['Heat island:', 'It is a town that is warmer than the surrounding countryside.']]),
    { title: '1. Nature of the Surface', intro: 'The nature of the surface influences temperature in the following ways:',
      items: [['Land surfaces:', 'Land has a low specific heat, so it heats up quickly by day and in summer and cools quickly at night and in winter. Heat also stays in the top few centimetres of rock and soil, which makes land temperatures extreme.', 'continentality_big.png', 'land and sea'],
        ['Water surfaces:', 'Water heats and cools slowly because it has a high specific heat, it is transparent and it is mixed by waves and currents. It therefore stores heat and moderates the temperature of the air above it.'],
        ['Distance from the sea:', 'Coastal places such as Douala and Kribi have a small range of temperature because the sea keeps them mild. Inland places such as Garoua and Maroua have a large range, with very hot days in March and April and cool nights in December and January.']] },
    { title: '2. Relief', intro: 'Relief influences temperature in the following ways:',
      items: [['Altitude above sea level:', 'Temperature falls by about 6.5 °C for every 1,000 m of height, because the air is thinner and further from the heated ground. This is why Ngaoundéré (about 1,100 m) and the Mandara Mountains are cooler than Garoua.', 'f2t_kilimanjaro.jpg', 'a snow-capped mountain in the tropics'],
        ['Aspect of slope:', 'In the northern hemisphere, the adret (south-facing slope) receives the rays of the sun more directly and is warmer and drier. The ubac (north-facing slope) is shaded, so it is cooler, and in the Alps villages and farms are built on the adret.', 'aspect_big.png', 'adret and ubac']] },
    { title: '3. Ocean Currents', intro: 'Ocean currents influence temperature in the following ways:',
      items: [['Warm currents:', 'Warm currents flow from the tropics towards the poles and warm the air of the coasts they touch. For example, the North Atlantic Drift keeps the ports of Norway free of ice in winter, and the Guinea Current keeps the coast of Cameroon warm.', 'ocean_currents_big.png', 'ocean currents'],
        ['Cold currents:', 'Cold currents flow from the poles towards the Equator and cool the air above them. For example, the Benguela Current cools the coast of Namibia and helps to form the Namib Desert.']] },
    { title: '4. Prevailing Winds', intro: 'Prevailing winds influence temperature in the following ways:',
      items: [['Winds from warm regions:', 'Winds carry the temperature of the regions they come from. For example, the Harmattan brings hot, dry air from the Sahara, so it raises the day temperature of Garoua in February and March.', 'f2t_harmattan.jpg', 'the Harmattan'],
        ['Winds from the sea or cold regions:', 'Winds that blow from the sea keep coastal places mild, as the westerlies do in western Europe. Winds from cold regions lower temperatures, as polar winds do in North America in winter.']] },
    { title: '5. Cloud Cover', intro: 'Cloud cover influences temperature in the following ways:',
      items: [['By day:', 'Clouds reflect a large part of the solar radiation back to space before it reaches the ground. Cloudy days, as in the rainy season, are therefore cooler than clear days.'],
        ['By night:', 'Clouds absorb the heat given off by the ground and send it back down, acting like a blanket. Cloudy nights are therefore warmer than clear nights, which explains the cold nights of the Harmattan season in the North.']] },
    { title: '6. Urbanisation: the Heat Island', intro: 'Towns are warmer than the countryside for the following reasons:',
      items: [['Artificial surfaces:', 'Concrete, tar and metal roofs absorb more solar energy than soil and plants and release it slowly at night. For this reason, a large town can be 2 to 5 °C warmer than the countryside after sunset.', 'heat_island_big.png', 'the urban heat island'],
        ['Heat from human activities:', 'Vehicles, motorbikes, air conditioners, kitchens and factories all release heat into the air. The more people and activities a town has, the more heat it produces.'],
        ['Lack of vegetation:', 'Towns have few trees and little open water, so there is less shade and less cooling by evaporation and transpiration. The heat is therefore used to warm the air instead.'],
        ['Buildings and pollution:', 'Tall buildings trap heat in narrow streets and slow down the wind that could carry it away. A layer of pollution over the town also absorbs heat and sends it back to the ground.']] },
  ],
  evaluation: [['Distinguish a maritime climate from a continental climate.', 'A maritime climate near the sea has small temperature ranges; a continental climate far inland has large ranges.'],
    ['Explain the double role of clouds on temperature.', 'By day they reflect sunlight and cool the ground; at night they trap heat and keep it warm.']],
  remediation: ['Temperature falls by about ______ °C per 1,000 m.', 'The direction a slope faces is its ______.', 'A town warmer than the countryside is an urban heat ______.'],
  remediationAnswers: '1. 6.5 2. aspect 3. island',
  homework: 'Define the environmental lapse rate.',
  hwAnswer: 'The environmental lapse rate is the rate at which air temperature falls with height, on average 6.5 °C per 1,000 m.',
  bilingual: [['Relief', 'Le relief'], ['Altitude', "L'altitude"], ['Wind', 'Le vent'], ['Cloud', 'Le nuage'], ['Urban heat island', "L'îlot de chaleur urbain"], ['Continentality', 'La continentalité']],
});

L.push({ no: 8, title: 'Vertical Distribution of Temperature', topic: T2, subtopic: 'Vertical Distribution of Heat in the Atmosphere', pointPerSlide: true,
  notions: 'Environmental lapse rate, terrestrial radiation, air density, pressure, expansion, adiabatic cooling.',
  focus: 'The decrease of temperature with height in the troposphere; the environmental lapse rate; reasons for the lapsing of temperature.',
  competence: 'Learners are able to explain why temperature falls with altitude and calculate temperatures at different heights.',
  objectives: ['Describe the vertical variation of temperature in the troposphere.', 'Define and use the environmental lapse rate.', 'Explain why the atmosphere is heated from below.', 'Explain the roles of air density and pressure.'],
  recall: ['The troposphere is the lowest layer.', 'The ground heats the air above it.', 'Mountains are cooler than plains.'],
  situation: 'During the holidays, your family drives from Garoua to Rhumsiki in the Mandara Mountains. As the car climbs past Guider, the air through the window becomes cooler and cooler, and at Rhumsiki you feel a little cold. Yet you are higher, so "closer to the Sun". You ask: "Why does it get colder as we go up, and by how much?"',
  sitQA: [['What is the problem in the situation?', 'The learner does not understand why temperature decreases with height.'],
    ['Is the air heated directly by the Sun?', 'No, mainly from below, by the ground.'],
    ['What is the rate of cooling with height called?', 'The environmental lapse rate.']],
  justification: 'This lesson explains why highlands are cool and helps us to calculate temperatures at different altitudes.',
  action: 'Use the lapse rate to estimate temperatures before travelling to highlands.',
  activities: [
    { sec: '1. LAPSE RATE', img: 'lapse_rate_big.png', caption: 'Temperature and height.', q: 'If Garoua (about 200 m) is at 35 °C, what is the temperature at 1,200 m?', a: '35 − 6.5 = 28.5 °C.', noProj: 'do the calculation on the board.' },
    { sec: '1. LAPSE RATE', img: 'lsa_mtcameroon.jpg', caption: 'Mount Cameroon.', q: 'Why is the summit of Mount Cameroon cold while Buea is warm?', a: 'The summit (4,095 m) is about 25 °C cooler because of altitude.', noProj: 'compare Buea and the summit.' },
    { sec: '2. REASONS', img: 'heated_below_big.png', caption: 'The atmosphere is heated from below.', q: 'Where is the air warmest in the troposphere?', a: 'Near the ground, the source of heat.', noProj: 'feel the air above hot ground.' },
    { sec: '2. REASONS', img: 'met2_elr.png', caption: 'Why temperature falls with height.', q: 'Why does thin air at altitude hold little heat?', a: 'It has fewer gas molecules, dust and water vapour to absorb heat.', noProj: 'list the three reasons.' },
    { sec: '2. REASONS', img: 'parcel.gif', caption: 'Animation: rising air expands and cools.', q: 'What happens to rising air as pressure falls?', a: 'It expands and cools.', noProj: 'feel the cold gas from a spray.' },
  ],
  summary: [
    D([['Environmental lapse rate (ELR):', 'It is the rate at which air temperature falls with height, on average 6.5 °C per 1,000 m.'],
      ['Adiabatic change:', 'It is a change of temperature of rising or sinking air caused by expansion or compression, without heat being added or removed.'],
      ['Terrestrial radiation:', 'It is the long-wave heat given off by the surface of the Earth.']]),
    { title: '1. Nature of the Variation of Temperature with Height', intro: 'Temperature varies with height in the following way:',
      items: [['General rule:', 'In the troposphere, temperature falls as altitude increases, on average by 6.5 °C for every 1,000 m. This fall is called the environmental lapse rate, but it changes with the time of day, the season and the place.', 'lapse_rate_big.png', 'the fall of temperature with height'],
        ['Worked example:', 'If it is 35 °C in Garoua (about 200 m), a place 1,000 m higher, at 1,200 m, would be at about 35 − 6.5 = 28.5 °C. The same calculation shows why highland towns are cooler than lowland towns.'],
        ['Mountains in the tropics:', 'The summit of Mount Cameroon (4,095 m) is about 25 °C cooler than the coast at Limbe, and it can have frost. Kilimanjaro, close to the Equator, even has permanent snow.', 'lsa_mtcameroon.jpg', 'Mount Cameroon']] },
    { title: '2. Reasons for the Vertical Lapsing of Temperature', intro: 'Temperature falls with height for the following reasons:',
      items: [['Heating from below:', 'Sunlight passes through the air and heats the ground, which then gives off heat to the air above it. The air is therefore warmest near the ground and cooler as we move away from it.', 'heated_below_big.png', 'the air heated from below'],
        ['Denser air near the ground:', 'Gravity keeps most of the gases, water vapour and dust near the ground. These absorb and keep terrestrial radiation, so the lower air holds more heat.', 'met2_elr.png', 'density and temperature'],
        ['Thin air at high altitudes:', 'Higher up, the air contains fewer molecules and less water vapour. It can therefore absorb and keep only a little heat, even if it receives strong sunshine.'],
        ['Adiabatic cooling:', 'When air rises, it meets lower pressure, expands and cools, without losing heat to its surroundings. This adiabatic cooling makes rising air colder with height.', 'parcel_last.png', 'a rising parcel of air']] },
  ],
  evaluation: [['Why is it colder at the top of a mountain than on the plain although it is "closer to the Sun"?', 'The air is heated from the ground; higher air is thinner, holds less heat and cools by expansion.'],
    ['If it is 30 °C at sea level, what is the temperature at 2,000 m?', '30 − (2 × 6.5) = 17 °C.']],
  remediation: ['Temperature falls with height in the ______.', 'The average lapse rate is ______ °C per 1,000 m.', 'Rising air expands and ______.'],
  remediationAnswers: '1. troposphere 2. 6.5 3. cools',
  homework: 'Define a temperature inversion.',
  hwAnswer: 'A temperature inversion is a situation in which temperature increases with height instead of decreasing.',
  bilingual: [['Altitude', "L'altitude"], ['Lapse rate', 'Le gradient thermique'], ['Atmosphere', "L'atmosphère"], ['Air density', "La densité de l'air"], ['Terrestrial radiation', 'Le rayonnement terrestre'], ['Pressure', 'La pression']],
});

L.push({ no: 9, title: 'Temperature Inversion', topic: T2, subtopic: 'Vertical Distribution of Heat in the Atmosphere', pointPerSlide: true,
  notions: 'Temperature inversion, surface (radiation) inversion, upper-air inversion, fog, smog, frost, stability.',
  focus: 'Meaning and types of temperature inversion; causes of surface inversion; effects on weather and human activities (fog, pollution, frost).',
  competence: 'Learners are able to explain the formation of temperature inversions and their effects, such as morning haze in the Benue valley.',
  objectives: ['Define a temperature inversion.', 'Distinguish surface and upper-air inversions.', 'Explain the conditions for a surface inversion.', 'Explain the effects of inversions.'],
  recall: ['Temperature normally falls with height.', 'The ground loses heat at night.', 'The Harmattan air is very dry.'],
  situation: 'On an early January morning in Garoua, you walk to school. The air near the ground is surprisingly cold on your legs, and a low haze of dust and smoke from cooking fires hangs in the air without rising. You have learnt that air gets colder with height. You ask: "Why is the air colder at the ground this morning, and why does the smoke not rise?"',
  sitQA: [['What is the problem in the situation?', 'The learner does not understand the temperature inversion.'],
    ['What is this condition called?', 'A temperature inversion: cold air below warmer air.'],
    ['Why does the smoke not rise?', 'The warm layer above acts like a lid that stops rising air.']],
  justification: 'This lesson explains morning fog and haze, air pollution and frost, which affect health, transport and farming.',
  action: 'Avoid burning waste on calm, cold mornings, and drive carefully in fog and haze.',
  activities: [
    { sec: '1. MEANING', img: 'inversion_graph_big.png', caption: 'Temperature in an inversion.', q: 'How does temperature change with height in an inversion?', a: 'It increases instead of decreasing.', noProj: 'draw the normal and the inverted line.' },
    { sec: '1. MEANING', img: 'inversion.gif', caption: 'Animation: a night inversion forms.', q: 'Where is the coldest air in a surface inversion?', a: 'Just above the ground.', noProj: 'describe a cold early morning.' },
    { sec: '2. CAUSES', img: 'met2_inv_causes.png', caption: 'Conditions for an inversion.', q: 'Why do clear skies help an inversion to form?', a: 'Heat escapes from the ground to space, so the ground and the air above it cool quickly.', noProj: 'compare cloudy and clear nights.' },
    { sec: '3. EFFECTS', img: 'lsa_cloudsea.jpg', caption: 'Fog in a valley.', q: 'Why does fog form in valleys during an inversion?', a: 'The cold air near the ground is cooled to its dew point.', noProj: 'describe fog over the Benue.' },
    { sec: '3. EFFECTS', img: 'lsa_smog.jpg', caption: 'Smog over a city.', q: 'Give one health effect of pollution trapped by an inversion.', a: 'Coughing and breathing problems.', noProj: 'discuss smoke from cooking fires.' },
  ],
  summary: [
    D([['Temperature inversion:', 'It is a situation in which temperature increases with height, so warm air lies above cold air.'],
      ['Capping inversion:', 'It is a warm layer of air aloft that stops rising air and clouds from going higher.'],
      ['Subsidence inversion:', 'It is an inversion formed when a large mass of air sinks slowly and warms by compression.'],
      ['Fog:', 'It is a cloud at ground level that reduces visibility to less than 1 km.']]),
    { title: '1. Meaning of Temperature Inversion', intro: 'Temperature inversion is explained as follows:',
      items: [['Temperature inversion:', 'Normally, temperature falls with height, but during an inversion a layer of warm air lies above cooler air. This warm layer acts like a lid that stops the cold air below from rising, so the air becomes very stable.', 'inversion_graph_big.png', 'a temperature inversion']] },
    { title: '2. Types of Temperature Inversion', sub: 'A) Surface Inversions', intro: 'The surface inversions are the following:',
      items: [['Radiation (ground) inversion:', 'On clear, calm nights, the ground loses its heat quickly by radiation and cools the air in contact with it. The air near the ground becomes colder than the air above, and this is the most common type of inversion.', 'inversion_last.png', 'a surface inversion'],
        ['Valley inversion:', 'At night, cold, heavy air on the slopes drains down and collects in valleys and basins. The valley floor becomes colder than the slopes above, as happens in the Benue valley in the Harmattan season.']] },
    { title: '2. Types of Temperature Inversion', sub: 'B) Above-Surface (Upper-Air) Inversions', intro: 'The above-surface inversions are the following:',
      items: [['Subsidence inversion:', 'In high-pressure areas, a large mass of air sinks slowly and is warmed by compression. A warm layer then forms a few hundred metres above the ground, as over the Sahara and the subtropical oceans.'],
        ['Frontal inversion:', 'Along a front, warm air rises over cold, heavy air. The warm air above the cold air forms an inversion that slopes along the front.'],
        ['Capping inversion:', 'A warm layer at the top of the lowest part of the atmosphere acts as a cap on rising air. It stops clouds from growing, but if strong heating breaks through it, violent storms can develop.']] },
    { title: '3. Causes of a Surface Inversion', intro: 'A surface inversion forms best under the following conditions:',
      items: [['Long nights:', 'Long nights give the ground more time to lose heat by terrestrial radiation. This is why inversions are strongest in winter in the temperate regions.', 'met2_inv_causes.png', 'the causes of inversions'],
        ['Clear skies and dry air:', 'Without clouds, and in dry air such as that of the Harmattan, heat escapes quickly to space. The ground and the air near it therefore cool rapidly after sunset.'],
        ['Calm air:', 'Without wind, the cold, heavy air is not mixed with the warmer air above. It therefore stays near the ground and forms a cold layer.'],
        ['Valleys and basins:', 'Cold air flows down the slopes at night like water and collects in low places. Valleys and basins are therefore the places where inversions are most frequent.']] },
    { title: '4. Effects on Weather Conditions and Man', sub: 'A) Effects on Weather', intro: 'Temperature inversions have the following effects on weather:',
      items: [['Stable air and clear skies:', 'The warm layer stops air from rising, so clouds and rain cannot form. For this reason, inversions give dry weather, as in the Sahara and on coastal deserts.'],
        ['Frost:', 'In cold regions and on high mountains, the air trapped near the ground can fall below 0 °C. Frost then forms on the ground and on plants.', 'lsa_frost.jpg', 'frost'],
        ['Haze and low clouds:', 'Moisture and dust are trapped below the warm layer. They form a layer of haze or flat stratus clouds under the inversion.']] },
    { title: '4. Effects on Weather Conditions and Man', sub: 'B) Effects on Man', intro: 'Temperature inversions have the following effects on man:',
      items: [['Air pollution:', 'Smoke, exhaust fumes and dust cannot rise and stay trapped near the ground, forming smog. This causes breathing problems, as in the London smog of 1952, which killed about 4,000 people.', 'lsa_smog.jpg', 'smog'],
        ['Danger for transport:', 'Fog and smog reduce visibility on roads and at airports. They cause road accidents and delay or cancel flights.'],
        ['Damage to crops:', 'Frost in valleys destroys crops such as coffee, tea and fruit trees. For this reason, farmers in temperate regions plant orchards on slopes above the cold valley floors.']] },
    { title: '5. Fog Formation', intro: 'Fog is formed in the following ways:',
      items: [['Radiation fog:', 'On clear, calm nights, the air near the cold ground is cooled to its dew point and its vapour condenses into droplets. This fog is common in valleys and near rivers in the early morning and clears as the sun heats the ground.', 'lsa_cloudsea.jpg', 'fog in the valleys'],
        ['Advection fog:', 'When warm, moist air moves over a cold surface, such as a cold sea current, it is cooled to its dew point. This fog forms along coasts such as San Francisco and the Namib coast.', 'f4_fog.jpg', 'fog']] },
  ],
  evaluation: [['How do a clear sky and calm winds help an inversion to form at night?', 'Clear skies let the ground lose heat quickly; calm air lets the cold air stay near the ground without mixing.'],
    ['Give two effects of temperature inversion on human activities.', 'Fog and reduced visibility, trapped pollution and health problems, frost damaging crops (any two).']],
  remediation: ['In an inversion, temperature ______ with height.', 'A mixture of smoke and fog is ______.', 'Inversions are strongest on ______ and calm nights.'],
  remediationAnswers: '1. increases 2. smog 3. clear',
  homework: 'Define relative humidity.',
  hwAnswer: 'Relative humidity is the amount of water vapour in the air compared with the maximum it can hold at that temperature, in %.',
  bilingual: [['Inversion', "L'inversion"], ['Fog', 'Le brouillard'], ['Pollutant', 'Le polluant'], ['Visibility', 'La visibilité'], ['Frost', 'Le gel'], ['Smog', 'Le smog']],
});

L.push({ no: 10, title: 'Nature of Moisture', topic: T3, subtopic: 'Atmospheric Humidity', pointPerSlide: true,
  notions: 'Evapotranspiration, humidity, condensation, sublimation, freezing, saturation, dew point.',
  focus: 'Meaning and sources of moisture; the three states of moisture; absolute and relative humidity; spatial distribution of humidity; factors of humidity; relevance of moisture on weather and man.',
  competence: 'Learners are able to explain the humidity of the air in the rainy and dry seasons of Garoua and calculate relative humidity.',
  objectives: ['Define moisture and identify its sources.', 'Describe the three states of moisture.', 'Distinguish absolute and relative humidity.', 'Describe the spatial distribution of humidity.', 'Explain the factors and the relevance of atmospheric moisture on weather and man.'],
  recall: ['Water vapour is a variable gas.', 'Latent heat is stored in water vapour.', 'The Harmattan is very dry.'],
  situation: 'In August, during the rainy season in Garoua, you play football with friends. Although the sun is not very hot, you sweat a lot and your clothes feel damp and sticky. In January, during the Harmattan, the air was so dry that your lips cracked and the same game did not make you feel so uncomfortable. You ask: "What invisible thing in the air makes it so sticky in August and so dry in January?"',
  sitQA: [['What is the problem in the situation?', 'The learner does not know the nature of atmospheric moisture.'],
    ['What is the invisible thing in the air?', 'Water vapour (moisture).'],
    ['Where does the moisture around Garoua come from?', 'Evaporation from the Benue and Lake Lagdo, the soil, and transpiration from plants.']],
  justification: 'This lesson explains humidity, which controls clouds, rain and our comfort.',
  action: 'Drink enough water in dry, hot weather and protect water bodies and vegetation that feed moisture to the air.',
  activities: [
    { sec: '1. SOURCES', img: 'water_cycle.gif', caption: 'Animation: the water cycle.', q: 'Name two sources of moisture in the air.', a: 'Evaporation from seas, lakes and rivers, and transpiration from plants.', noProj: 'draw the water cycle.' },
    { sec: '2. STATES', img: 'lsa_ice.jpg', caption: 'Ice.', q: 'In which three states can water exist in the atmosphere?', a: 'Gas (vapour), liquid (droplets) and solid (ice crystals).', noProj: 'show ice, water and steam.' },
    { sec: '3. TYPES', img: 'humidity_big.png', caption: 'Warm air can hold more water vapour.', q: 'What does a relative humidity of 100 % mean?', a: 'The air is saturated.', noProj: 'fill a cup to the brim.' },
    { sec: '4. DISTRIBUTION', img: 'equatorial_world_big.png', caption: 'The equatorial regions.', q: 'Why is the air very humid in the Congo Basin?', a: 'High temperatures and much water from rivers and forests give strong evaporation and transpiration.', noProj: 'show the equator on a globe.' },
    { sec: '5. FACTORS', img: 'f2t_harmattan.jpg', caption: 'Harmattan haze.', q: 'Why is the air of Garoua so dry in January?', a: 'The Harmattan brings dry air from the Sahara.', noProj: 'describe the Harmattan season.' },
  ],
  summary: [
    D([['Evapotranspiration:', 'It is the total loss of water to the atmosphere by evaporation from water and soil and by transpiration from plants.'],
      ['Condensation:', 'It is the change of water vapour into liquid water when air is cooled to its dew point.'],
      ['Sublimation:', 'It is the direct change of ice into water vapour, or of water vapour into ice, without passing through the liquid state.'],
      ['Freezing:', 'It is the change of liquid water into ice at 0 °C.'],
      ['Saturation:', 'It is the state of air that holds the maximum water vapour possible at its temperature.'],
      ['Dew point:', 'It is the temperature at which air becomes saturated and condensation begins.']]),
    { title: '1. Meaning and Sources of Moisture', sub: 'A) Meaning of Moisture', intro: 'Moisture is defined as follows:',
      items: [['Moisture:', 'Moisture, also known as atmospheric humidity, is the water held in the atmosphere, mainly as invisible water vapour but also as droplets and ice crystals. In a strict sense, humidity refers only to the water vapour. Although it forms less than 4 % of the air, moisture is the source of all clouds and precipitation.']] },
    { title: '1. Meaning and Sources of Moisture', sub: 'B) Sources of Moisture', intro: 'The atmosphere receives its moisture from the following sources:',
      items: [['Oceans and seas:', 'Oceans cover about 71 % of the Earth and supply about 86 % of the water vapour in the air by evaporation. This is why the air over the Gulf of Guinea and around Douala is always humid.'],
        ['Lakes and rivers:', 'Inland water bodies such as Lake Lagdo, the Benue and Lake Chad also lose water by evaporation, especially in the hot season. They make the air around them more humid than the surrounding dry land.', 'f2t_lagdo.jpg', 'Lake Lagdo'],
        ['Moist soil:', 'After rain, the sun heats the soil and its water evaporates into the air. This source is important in the rainy season but becomes very weak in the dry season when soils dry out.'],
        ['Plants:', 'Plants take water from the soil through their roots and release it as vapour through the pores (stomata) of their leaves. With evaporation, this transpiration forms evapotranspiration, which makes the air over forests such as the Congo Basin very humid.', 'evapotranspiration_big.png', 'evapotranspiration']] },
    { title: '2. The Three States of Moisture', intro: 'Moisture exists in the atmosphere in the following three states:',
      items: [['Gaseous state (water vapour):', 'Water vapour is an invisible gas formed when water evaporates or when ice sublimates. It is the most common state of moisture and it stores latent heat, which is released when it condenses.'],
        ['Liquid state:', 'When water vapour is cooled to its dew point, it condenses into tiny droplets. These droplets form clouds, fog, mist and dew, and when they grow big enough they fall as drizzle or rain.', 'lsa_dew.jpg', 'dew drops on grass'],
        ['Solid state:', 'When droplets freeze, or when vapour changes directly into ice by sublimation, ice crystals are formed. They make up high clouds such as cirrus and fall as snow, hail or frost in cold regions and on high mountains.', 'lsa_snow.jpg', 'snow']] },
    { title: '3. Types of Atmospheric Humidity', intro: 'Atmospheric humidity is expressed in the following two types:',
      items: [['Absolute humidity:', 'Absolute humidity is the mass of water vapour in a given volume of air, expressed in grams per cubic metre (g/m³). For example, 15 g/m³ means 15 grams of vapour in each cubic metre of air. It is high in hot equatorial air and very low in cold polar air and in deserts.', 'humidity_big.png', 'warm air can hold more water vapour'],
        ['Relative humidity (RH):', 'Relative humidity compares the vapour in the air with the maximum the air can hold at the same temperature, in %: RH = actual vapour ÷ maximum vapour × 100. Air at 30 °C can hold about 30 g/m³, so if it contains 15 g/m³, its RH is 50 %. At 100 % the air is saturated and condensation begins.', 'met2_humidity.png', 'relative humidity and temperature']] },
    { title: '4. Spatial Distribution of Humidity', intro: 'Humidity is distributed over the Earth as follows:',
      items: [['Equatorial regions:', 'High temperatures and abundant water from oceans, rivers and forests give very high humidity all year. In the Congo Basin and on the Guinea coast, relative humidity is often above 80 %.', 'equatorial_world_big.png', 'the equatorial regions'],
        ['Tropical deserts (15° to 30° N and S):', 'In the subtropical high-pressure belts, sinking air is warmed and dried, so relative humidity is very low, often under 20 %. The Sahara and the Kalahari therefore have clear skies and very little rain.', 'deserts_world_big.png', 'the hot deserts'],
        ['Coasts and continental interiors:', 'Air over oceans and along coasts is humid because of constant evaporation from the sea. Humidity decreases towards the interior of continents, which is why Douala is far more humid than Maroua.'],
        ['Polar regions:', 'Very cold air can hold little water vapour, so absolute humidity is extremely low. However, relative humidity can be high because this cold air is close to saturation even with little vapour.']] },
    { title: '5. Factors that Influence Atmospheric Humidity', intro: 'Atmospheric humidity is influenced by the following factors:',
      items: [['Temperature:', 'Warm air can hold more water vapour than cold air, so a change of temperature changes relative humidity even when the amount of vapour stays the same. When the air cools at night, RH rises and dew or fog forms at dawn; when it warms in the afternoon, RH falls.', 'f4_fog.jpg', 'morning fog'],
        ['Nearness to water bodies:', 'Places near seas, lakes and rivers receive more water vapour by evaporation. For this reason, coastal and lakeside areas are more humid than places far inland.'],
        ['Vegetation cover:', 'Dense vegetation releases large amounts of water vapour by transpiration. Forested areas are therefore more humid than bare land, and deforestation lowers humidity.', 'f2t_rainforest.jpg', 'a dense forest'],
        ['Winds and air masses:', 'Winds bring the humidity of the regions they come from. In Garoua, the moist south-west monsoon from the Atlantic raises RH above 70 % in the rainy season, while the dry Harmattan from the Sahara lowers it below 20 % in the dry season.', 'f2t_harmattan.jpg', 'Harmattan haze']] },
    { title: '6. Relevance of Atmospheric Moisture', sub: 'A) On Weather', intro: 'Atmospheric moisture is important for weather in the following ways:',
      items: [['Formation of clouds and precipitation:', 'All clouds, fog, dew and precipitation come from the condensation of water vapour. Moisture is therefore the source of the rain that falls on the Earth; without it, there would be no rain at all.', 'lsa_cloudsea.jpg', 'clouds'],
        ['Transfer of heat energy:', 'Water vapour takes latent heat during evaporation and releases it when it condenses. In this way, moisture carries heat from warm oceans and low latitudes to cooler regions and supplies the energy of thunderstorms.', 'f2t_storm.jpg', 'a storm cloud'],
        ['Regulation of temperature:', 'Water vapour is a greenhouse gas that absorbs the heat radiated by the Earth and keeps the lower air warm at night. It thus reduces the daily range of temperature, which is why humid regions do not become as cold at night as dry deserts.']] },
    { title: '6. Relevance of Atmospheric Moisture', sub: 'B) On Man', intro: 'Atmospheric moisture is important for man in the following ways:',
      items: [['Water supply:', 'The rain formed from atmospheric moisture fills the rivers, lakes, springs and wells that people use every day. It also fills the reservoirs of dams such as Lagdo, which produce hydroelectricity for the North.', 'f2t_lagdo.jpg', 'Lake Lagdo'],
        ['Agriculture and livestock:', 'Moisture supplies the rain and dew that crops and pastures need to grow. In the North, farmers plant millet, maize and cotton at the start of the rains, and herders depend on the green pastures of the rainy season.', 'f4_ricefield.jpg', 'a rice field'],
        ['Human comfort and health:', 'A moderate humidity keeps the skin, eyes, nose and throat moist and protects them from dryness and dust. It also makes the hot season more bearable, because the air is cooler and less dusty than during the dry Harmattan.']] },
  ],
  evaluation: [['Distinguish absolute humidity from relative humidity.', 'Absolute humidity is the mass of vapour in a volume of air; relative humidity compares this amount with the maximum possible at that temperature, in %.'],
    ['Explain why relative humidity rises at night.', 'The air cools and can hold less vapour, so the same amount of vapour gives a higher percentage.']],
  remediation: ['The water released by plants through their leaves is called ______.', 'Air at 100 % relative humidity is ______.', 'The temperature at which condensation begins is the ______ point.'],
  remediationAnswers: '1. transpiration 2. saturated 3. dew',
  homework: 'Name three types of clouds.',
  hwAnswer: 'Cumulus, cumulonimbus, stratus and cirrus (any three).',
  bilingual: [['Moisture', "L'humidité"], ['Water vapour', "La vapeur d'eau"], ['Evapotranspiration', "L'évapotranspiration"], ['Relative humidity', "L'humidité relative"], ['Condensation', 'La condensation'], ['Sublimation', 'La sublimation'], ['Dew point', 'Le point de rosée']],
});

L.push({ no: 11, title: 'Forms of Condensation and Precipitation', topic: T3, subtopic: 'Precipitation', pointPerSlide: true,
  notions: 'Condensation, dew point, condensation nuclei, cumulus, cumulonimbus, stratus, cirrus, fog, mist, dew, drizzle, rain, hail, snow, frost, convectional, orographic and frontal rainfall.',
  focus: 'Forms of condensation (clouds and their classification, fog and mist); forms of precipitation (liquid and solid); types of rainfall.',
  competence: 'Learners are able to identify clouds and forms of precipitation and explain the types of rainfall, especially the thunderstorms of Garoua.',
  objectives: ['Define condensation and precipitation.', 'Classify the main types of clouds and their weather.', 'Distinguish fog and mist.', 'Describe liquid and solid precipitation.', 'Explain convectional, orographic and frontal rainfall.'],
  recall: ['Relative humidity rises when air cools.', 'Aerosols act as condensation nuclei.', 'Rising air expands and cools.'],
  situation: 'On a hot July afternoon in Garoua, the sky is blue with a few white, puffy clouds. During the afternoon, you watch them grow upwards like mountains, and their bases become dark grey. Thunder rumbles, and within an hour a heavy rain floods the streets before stopping as suddenly as it began. You ask: "How does invisible vapour become clouds, and how can a sunny day turn into such a storm?"',
  sitQA: [['What is the problem in the situation?', 'The learner does not know how clouds and rain form.'],
    ['What turns vapour into cloud droplets?', 'Condensation.'],
    ['What type of rain is this storm?', 'Convectional rainfall from a cumulonimbus cloud.']],
  justification: 'This lesson helps us to read the sky and to understand the rains on which farming in the North depends.',
  action: 'Observe the clouds to anticipate storms and shelter from lightning.',
  activities: [
    { sec: '1. CLOUDS', img: 'cloud_types_big.png', caption: 'The main types of clouds.', q: 'Which cloud brings thunderstorms?', a: 'The cumulonimbus.', noProj: 'draw the four cloud types.' },
    { sec: '1. CLOUDS', img: 'lsa_cumulus.jpg', caption: 'Cumulus clouds.', q: 'What weather do small cumulus clouds usually indicate?', a: 'Fair weather.', noProj: 'look at today\'s sky.' },
    { sec: '2. PRECIPITATION', img: 'lsa_dew.jpg', caption: 'Dew on grass.', q: 'Is dew a form of precipitation?', a: 'No, it is condensation on cool surfaces.', noProj: 'look at grass at dawn.' },
    { sec: '2. PRECIPITATION', img: 'lsa_hail.jpg', caption: 'Hailstones.', q: 'In which cloud do hailstones form?', a: 'In cumulonimbus clouds during violent storms.', noProj: 'describe a hailstorm.' },
    { sec: '3. TYPES OF RAINFALL', img: 'rainfall_types_big.png', caption: 'Three types of rainfall.', q: 'What is the dry side of a mountain called?', a: 'The rain shadow (leeward side).', noProj: 'draw orographic rainfall.' },
  ],
  summary: [
    D([['Condensation:', 'It is the change of water vapour into liquid water when air cools to its dew point.'],
      ['Condensation nuclei:', 'They are tiny particles of dust, salt or smoke on which droplets form.'],
      ['Precipitation:', 'It is any form of water, liquid or solid, that falls from clouds to the ground.'],
      ['Rain shadow:', 'It is the dry leeward side of a mountain.']]),
    { title: '1. Cloud Formation', sub: 'A) How Clouds Form', intro: 'Clouds form in the following way:',
      items: [['Cooling of rising air:', 'When moist air rises, it meets lower pressure, expands and cools by about 10 °C per 1,000 m. When it reaches its dew point, it becomes saturated and its vapour starts to condense.', 'cloud_types_big.png', 'the types of clouds'],
        ['Condensation on nuclei:', 'The vapour condenses on tiny particles of dust, salt or smoke and forms droplets about 0.02 mm wide. Billions of these droplets, or ice crystals where it is very cold, make up a cloud.']] },
    { title: '1. Cloud Formation', sub: 'B) Classification and Associated Weather', intro: 'Clouds are classified by height and shape, and each type announces the following weather:',
      items: [['High clouds (above 6,000 m):', 'Cirrus, cirrostratus and cirrocumulus are thin, white clouds made of ice crystals. Cirrus alone indicates fair weather, but cirrostratus spreading over the sky often announces rain within a day.'],
        ['Middle clouds (2,000 to 6,000 m):', 'Altostratus and altocumulus are grey or white sheets or patches. When altostratus thickens and the sun disappears behind it, a front is approaching and steady rain will soon follow.'],
        ['Low clouds (below 2,000 m):', 'Stratus and nimbostratus are grey layers that cover the whole sky. Stratus gives dull weather with drizzle, while nimbostratus gives long periods of steady rain.'],
        ['Clouds of vertical development:', 'Cumulus are puffy clouds with flat bases that show fair weather when they stay small. When they grow into huge cumulonimbus, they bring heavy showers, thunder, lightning and sometimes hail, as in Garoua in the rainy season.', 'f4_cumulonimbus.jpg', 'a cumulonimbus cloud']] },
    { title: '2. Fog and Mist', intro: 'Fog and mist are distinguished as follows:',
      items: [['Fog:', 'Fog is a cloud at ground level formed when the air near the surface is cooled to its dew point. It reduces visibility to less than 1 km and is dangerous for road and air transport.', 'f4_fog.jpg', 'fog'],
        ['Mist:', 'Mist is a thinner cloud of droplets at ground level, with visibility between 1 and 2 km. It forms in the same way as fog, often in the early morning over rivers and valleys, and disappears quickly when the sun heats the ground.']] },
    { title: '3. Forms of Precipitation', sub: 'A) Solid Forms', intro: 'The solid forms of precipitation are the following:',
      items: [['Snow:', 'Snow is made of ice crystals that grow in very cold clouds and join to form flakes. It falls when the air is below 0 °C down to the ground, in temperate and polar regions and on high mountains.', 'lsa_snow.jpg', 'snow'],
        ['Sleet:', 'Sleet is made of small pellets of ice formed when raindrops freeze as they fall through a cold layer of air near the ground. In Britain, the word also means a mixture of rain and snow.'],
        ['Hail:', 'Hailstones are balls of ice formed in cumulonimbus clouds, where strong up-currents carry drops up and down through freezing air. Each trip adds a layer of ice until the stone is too heavy and falls, damaging crops and roofs.', 'lsa_hail.jpg', 'hailstones'],
        ['Frost and rime:', 'Frost is a white layer of ice crystals formed when water vapour changes directly into ice on surfaces below 0 °C. Rime forms when fog droplets freeze on contact with cold trees, wires and rocks.', 'lsa_frost.jpg', 'frost']] },
    { title: '3. Forms of Precipitation', sub: 'B) Liquid Forms', intro: 'The liquid forms of precipitation are the following:',
      items: [['Dew:', 'Dew is made of droplets that form on cool surfaces such as grass and leaves on clear, calm nights. The air touching them is cooled to its dew point, so strictly speaking dew is condensation and not falling precipitation.', 'lsa_dew.jpg', 'dew'],
        ['Drizzle:', 'Drizzle is made of very small drops, less than 0.5 mm wide, that fall slowly from low stratus clouds. It gives only small amounts of water but can last for hours.'],
        ['Rainfall (formation process):', 'Rain forms when cloud droplets grow large enough to fall, either by colliding and joining together in warm clouds, or by the growth of ice crystals that melt as they fall. Raindrops are larger than 0.5 mm and fall faster than drizzle.', 'f4_heavyrain.jpg', 'heavy rain']] },
    { title: '4. Types of Rainfall', intro: 'Rainfall is classified into the following three types according to how the air is made to rise:',
      items: [['Convectional rainfall:', 'Strong heating of the ground makes moist air rise quickly and form cumulonimbus clouds. It gives short, heavy afternoon storms with thunder, as in the equatorial regions and in Garoua in the rainy season.', 'rainfall_types_big.png', 'the three types of rainfall'],
        ['Orographic (relief) rainfall:', 'Moist winds from the sea are forced to rise over mountains, cool and give heavy rain on the windward side. The leeward side receives little rain and is called a rain shadow, as on the eastern side of Mount Cameroon.'],
        ['Cyclonic (frontal) rainfall:', 'Where a warm air mass meets a cold one, the lighter warm air rises slowly over the cold air along a front. It gives long periods of steady rain, as in the temperate regions of Europe.']] },
  ],
  evaluation: [['Explain how a hot sunny day in Garoua can lead to a heavy afternoon storm.', 'The ground heats the air, which rises quickly, cools and condenses into a cumulonimbus that gives convectional rain.'],
    ['Distinguish dew from drizzle.', 'Dew is condensation on cool surfaces; drizzle is fine rain falling from clouds.']],
  remediation: ['Thunderstorm clouds are ______.', 'The dry side of a mountain is the rain ______.', 'Rain from warm air rising over cold air is ______ rain.'],
  remediationAnswers: '1. cumulonimbus 2. shadow 3. frontal (cyclonic)',
  homework: 'Name the world\'s wettest belt of latitude.',
  hwAnswer: 'The equatorial belt, around the Equator.',
  bilingual: [['Cloud', 'Le nuage'], ['Rain', 'La pluie'], ['Condensation', 'La condensation'], ['Precipitation', 'Les précipitations'], ['Thunderstorm', "L'orage"], ['Hail', 'La grêle']],
});

L.push({ no: 12, title: 'Global Distribution of Precipitation', topic: T3, subtopic: 'Precipitation', pointPerSlide: true,
  notions: 'Pressure belts, ITCZ, subtropical high, temperate low, polar high, maritime and continental air masses, relief rainfall, rain shadow, continentality.',
  focus: 'The global pattern of precipitation and its primary factors (pressure belts, air masses); secondary factors (relief, distance from the sea, vegetation, currents, lakes, towns).',
  competence: 'Learners are able to explain the world pattern of rainfall and the contrast between Douala and Garoua.',
  objectives: ['Describe the global pattern of precipitation.', 'Explain the role of pressure belts.', 'Explain the role of air masses.', 'Explain the secondary factors of rainfall.'],
  recall: ['Rising air cools and forms clouds.', 'Relief forces air to rise.', 'The Harmattan is continental air.'],
  situation: 'In late March, the heat in Garoua is intense and there is no rain yet. Your uncle in Douala calls and complains that heavy rains have already started there and flooded his quarter. He says: "You people in Garoua are lucky with your long dry season!" You ask: "Why does Douala receive so much rain so early, while Garoua has less rain and a shorter rainy season?"',
  sitQA: [['What is the problem in the situation?', 'The learner does not know the factors of the distribution of rainfall.'],
    ['Why is Douala so wet?', 'It is near the equatorial low-pressure belt, on the coast, and at the foot of Mount Cameroon.'],
    ['Why is Garoua drier?', 'It is far inland and under the dry Harmattan for a long part of the year.']],
  justification: 'This lesson explains the world pattern of rainfall and the differences in water availability within Cameroon.',
  action: 'Save water during the long dry season and plan farming with the rainfall calendar.',
  activities: [
    { sec: '1. GLOBAL PATTERN', img: 'rain_latitude_big.png', caption: 'Rainfall by latitude.', q: 'Where is rainfall heaviest on the globe?', a: 'Around the Equator.', noProj: 'draw rainfall bars by latitude.' },
    { sec: '1. PRESSURE BELTS', img: 'pressure_belts_big.png', caption: 'The pressure belts.', q: 'Why are the great deserts near 30° N and S?', a: 'Air sinks in the subtropical high-pressure belts, so clouds do not form.', noProj: 'draw the pressure belts.' },
    { sec: '1. PRESSURE BELTS', img: 'f2t_erg.jpg', caption: 'The Sahara.', q: 'Which pressure belt lies over the Sahara?', a: 'The subtropical high-pressure belt.', noProj: 'locate the Sahara.' },
    { sec: '2. SECONDARY FACTORS', img: 'rain_compare_big.png', caption: 'Rainfall of Douala and Garoua.', q: 'Give one reason why Douala is wetter than Garoua.', a: 'It is on the coast, close to the moist monsoon air, and at the foot of Mount Cameroon.', noProj: 'compare the two towns.' },
    { sec: '2. SECONDARY FACTORS', img: 'met2_rain_factors.png', caption: 'Factors of rainfall.', q: 'How do forests increase rainfall?', a: 'They release water vapour by transpiration.', noProj: 'list the factors.' },
  ],
  summary: [
    D([['Pressure belt:', 'It is a zone of high or low pressure that circles the globe along a latitude.'],
      ['Intertropical Convergence Zone (ITCZ):', 'It is the equatorial low-pressure zone where the trade winds meet and air rises.'],
      ['Air mass:', 'It is a large body of air with similar temperature and humidity.'],
      ['Continentality:', 'It is the effect of distance from the sea, which makes inland areas drier and their temperatures more extreme.'],
      ['Insularity:', 'It is the effect of being surrounded by the sea, which makes islands and coasts wetter and milder.']]),
    { title: '1. Spatial Pattern of Distribution by Latitude', intro: 'Precipitation is distributed by latitude as follows:',
      items: [['Equatorial zone (0° to 10° N and S):', 'This zone receives the heaviest rainfall on Earth, usually more than 2,000 mm a year, with rain in every month. It is the zone of rainforests, such as the Congo Basin and the Amazon.', 'rain_latitude_big.png', 'rainfall and latitude'],
        ['Tropical and subtropical zones (10° to 30°):', 'Rainfall decreases away from the Equator, and the dry season becomes longer. Around 20° to 30°, it falls below 250 mm a year in the great hot deserts such as the Sahara.', 'deserts_world_big.png', 'the hot deserts'],
        ['Temperate zone (40° to 60°):', 'Rainfall rises again to a moderate amount, between about 500 and 1,500 mm a year. It falls in all seasons, especially on the western coasts of the continents.'],
        ['Polar zones (above 60°):', 'Precipitation is very low, often less than 250 mm a year, and falls mainly as snow. These regions are therefore called cold or ice deserts.', 'lsa_icecap.jpg', 'an ice cap']] },
    { title: '2. Primary Factors of Variation', sub: 'A) Pressure Belts', intro: 'The pressure belts explain this pattern in the following ways:',
      items: [['Equatorial low pressure (ITCZ):', 'Intense heating makes the air rise, expand and cool, so its vapour condenses into cumulonimbus clouds. This gives heavy convectional rain all year near the Equator.', 'pressure_belts_big.png', 'the pressure belts'],
        ['Subtropical high pressure (about 30° N and S):', 'Here, air sinks from high altitudes, is compressed and warms, so it can hold its vapour and no clouds form. This is why the great deserts, such as the Sahara and the Kalahari, lie along these latitudes.', 'f2t_erg.jpg', 'a sand desert'],
        ['Temperate low pressure (about 60° N and S):', 'Warm tropical air and cold polar air meet along the polar front. The warm air is forced to rise, which gives frontal rain throughout the year.'],
        ['Polar high pressure:', 'Very cold, dense air sinks over the poles and holds very little moisture. Precipitation is therefore very low.']] },
    { title: '2. Primary Factors of Variation', sub: 'B) Air Masses', intro: 'Air masses influence precipitation in the following ways:',
      items: [['Maritime air masses:', 'They form over the oceans and are moist, so they bring rain to the lands they cross. For example, the maritime tropical air of the south-west monsoon brings the rainy season to Cameroon from April to October in the North.'],
        ['Continental air masses:', 'They form over land and are dry, so they bring dry weather. For example, the continental tropical air of the Harmattan, from the Sahara, brings the dry season to northern Cameroon.', 'f2t_harmattan.jpg', 'the Harmattan']] },
    { title: '3. Secondary (Local) Factors', sub: 'A) Relief, the Sea and Ocean Currents', intro: 'Local rainfall is influenced by the following physical factors:',
      items: [['Relief:', 'Moist air forced to rise over mountains gives heavy rain on the windward side and a rain shadow on the leeward side. Debundscha, at the foot of Mount Cameroon, receives about 10,000 mm a year, one of the highest totals in the world.', 'met2_rain_factors.png', 'local factors of rainfall'],
        ['Distance from the sea (insularity and continentality):', 'Coasts and islands receive much moisture from the sea, while inland areas are far from it and drier. Douala receives about 4,000 mm a year, but Garoua only about 1,000 mm.', 'rain_compare_big.png', 'rainfall of Douala and Garoua'],
        ['Ocean currents:', 'Warm currents warm the air above them, which picks up moisture and brings rain to the coast. Cold currents cool the air, which becomes stable, so coasts along them are dry, like the Namib and Atacama deserts.']] },
    { title: '3. Secondary (Local) Factors', sub: 'B) Vegetation, Water Bodies and Towns', intro: 'Local rainfall is also influenced by the following factors:',
      items: [['Vegetation:', 'Forests release a lot of water vapour by transpiration, which feeds the clouds and encourages convectional rain. Deforestation therefore tends to reduce local rainfall.', 'f2t_rainforest.jpg', 'a rainforest'],
        ['Water bodies:', 'Large lakes and reservoirs, such as Lake Chad and Lake Lagdo, add water vapour to the air by evaporation. They can increase rainfall on their shores, especially on the side where the winds blow.', 'f2t_lake_chad.jpg', 'Lake Chad'],
        ['Urban effects:', 'Towns are warmer than the countryside and their air contains many dust particles. The rising warm air and these condensation nuclei can increase storms and rainfall over and downwind of big cities.']] },
  ],
  evaluation: [['Why does the Equator receive heavy rain all year while 30° N is very dry?', 'At the Equator, low pressure makes air rise and form rain clouds; at 30° N, high pressure makes air sink and warm, so no clouds form.'],
    ['Give two reasons why Douala is wetter than Garoua.', 'It is on the coast near moist monsoon air; Mount Cameroon forces the air to rise (relief rain).']],
  remediation: ['The equatorial low-pressure zone is the ______.', 'Deserts lie under the subtropical ______ pressure belts.', 'The dry side of a mountain is the rain ______.'],
  remediationAnswers: '1. ITCZ 2. high 3. shadow',
  homework: 'Define atmospheric pressure.',
  hwAnswer: 'Atmospheric pressure is the weight of the air pressing on a unit area of the surface of the Earth.',
  bilingual: [['Precipitation', 'Les précipitations'], ['Pressure belt', 'La ceinture de pression'], ['Relief', 'Le relief'], ['Windward side', 'Le versant au vent'], ['Rain shadow', "L'ombre pluviométrique"], ['Air mass', "La masse d'air"]],
});

module.exports = { B, L };
